  /* G: alternatives Rohrsystem mit Längsverschluss (Retrofit um bestehende Kabel) */
  var LAENGS = { 100: { lief: "151/415.102", ver: "151/433.002" }, 120: { lief: "151/415.103", ver: "151/433.003" }, 150: { lief: "151/415.104", ver: "151/433.003" } };
